package com.chahinaz.pos.operations;
import com.chahinaz.pos.audit.AuditService;import com.chahinaz.pos.employee.*;import jakarta.validation.constraints.*;import java.time.Instant;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class ApprovalService {private final ManagerApprovalRepository approvals;private final EmployeeRepository employees;private final AuditService audit;public ApprovalService(ManagerApprovalRepository a,EmployeeRepository e,AuditService au){approvals=a;employees=e;audit=au;}
 public record Input(@NotBlank @Size(max=40) String operationType,@NotBlank String requestingUsername,@NotBlank @Size(max=40) String targetType,@NotNull UUID targetId,@NotBlank @Size(min=3,max=500) String reason){} public record View(UUID id,String operationType,UUID requestingEmployeeId,UUID approvingEmployeeId,String targetType,UUID targetId,String reason,Instant approvedAt){}
 @Transactional public View approve(Input in,Authentication auth){Employee approver=employees.findByUsernameIgnoreCase(auth.getName()).orElseThrow();if(approver.getRole()==Role.TELLER)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Manager or Admin approval required");Employee requester=employees.findByUsernameIgnoreCase(in.requestingUsername()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Requesting employee not found"));if(in.reason()==null||in.reason().trim().length()<3)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Approval reason is required");ManagerApproval a=approvals.saveAndFlush(new ManagerApproval(in.operationType(),requester.getId(),approver.getId(),in.targetType(),in.targetId(),in.reason().trim()));audit.record(approver.getId(),"MANAGER_APPROVAL","manager_approval",a.id.toString(),null,a.operationType+" for "+a.targetId);return view(a);}
 @Transactional public UUID consume(UUID id,String operation,UUID requester,UUID target){if(id==null)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Valid manager approval required");ManagerApproval a=approvals.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Valid manager approval required"));if(a.consumedAt!=null||!a.operationType.equals(operation)||!a.requestingEmployeeId.equals(requester)||!a.targetId.equals(target))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Approval does not match this operation");a.consumedAt=Instant.now();approvals.save(a);return a.approvingEmployeeId;}
 private View view(ManagerApproval a){return new View(a.id,a.operationType,a.requestingEmployeeId,a.approvingEmployeeId,a.targetType,a.targetId,a.reason,a.approvedAt);}}
